assert len(GROUP_EXPECTATIONS)==14 and all(len(x)==10 for x in GROUP_EXPECTATIONS)

def apply_contracts(cases):
 for c in cases:
  if c['id'].startswith('S'):
   n=int(c['id'][1:])-1;c['expected']=GROUP_EXPECTATIONS[n//10][n%10]
  c['judgement_basis']={'model_fixture':'核对最终回答及原始模型消息、来源片段与引用核验、原始工具调用、合成存储/网络副作用、当前轮与历史权限。','probe':'运行指定原始边界函数或路由，核对受控返回/归属过滤/观察值；替身及只读适配单列。'}[c['mode']]
  c['execution_material']={k:c[k] for k in ['fixture','inject','history','fault','probe','stale','semantic','conflict'] if k in c}
 return cases
